// Anti-aliased bitmap fonts drawn straight into the sprite buffer (Canvas::text). LovyanGFX's VLW renderer needs ~3 ms
// for an 8-character label on the ESP32, which alone held the radar under 10 fps; this path is ~50x faster.
// Data is generated by tools/make_fonts.py into fonts_data.h and lives in flash.
#pragma once
#include <stdint.h>

struct Glyph {
  uint16_t cp;     // Unicode code point
  uint8_t w, h;    // bitmap size
  uint8_t adv;     // cursor advance
  int8_t dx, dy;   // bitmap left edge from the cursor; bitmap top above the baseline
  uint32_t off;    // into FontData::bitmap (w*h bytes of 8-bit alpha)
};

struct FontData {
  const Glyph* glyphs;  // sorted by cp
  uint16_t count;
  const uint8_t* bitmap;
  uint8_t ascent, descent, cap;  // cap: height of "H", used to centre text vertically
};
